import{_ as a,H as s,f as l,i as e}from"./chunks/framework.BH2BK_3i.js";const u=JSON.parse('{"title":"37 | 简单选择排序与堆排序：多趟排序与利用有序完全二叉树进行排序","description":"","frontmatter":{},"headers":[{"level":2,"title":"什么是简单选择排序？","slug":"什么是简单选择排序","link":"#什么是简单选择排序","children":[{"level":3,"title":"简单选择排序过程演示","slug":"简单选择排序过程演示","link":"#简单选择排序过程演示","children":[]},{"level":3,"title":"简单选择排序实现代码","slug":"简单选择排序实现代码","link":"#简单选择排序实现代码","children":[]}]},{"level":2,"title":"n2","slug":"n2","link":"#n2","children":[]},{"level":2,"title":"堆排序","slug":"堆排序","link":"#堆排序","children":[{"level":3,"title":"堆的基本概念","slug":"堆的基本概念","link":"#堆的基本概念","children":[]},{"level":3,"title":"堆排序算法","slug":"堆排序算法","link":"#堆排序算法","children":[]},{"level":3,"title":"堆排序实现代码","slug":"堆排序实现代码","link":"#堆排序实现代码","children":[]},{"level":3,"title":"堆中元素的插入和删除","slug":"堆中元素的插入和删除","link":"#堆中元素的插入和删除","children":[]},{"level":3,"title":"堆排序算法效率分析","slug":"堆排序算法效率分析","link":"#堆排序算法效率分析","children":[]}]},{"level":2,"title":"2i−1","slug":"_2i−1","link":"#_2i−1","children":[]},{"level":2,"title":"log","slug":"log","link":"#log","children":[]},{"level":2,"title":"log","slug":"log-1","link":"#log-1","children":[]},{"level":2,"title":"log","slug":"log-2","link":"#log-2","children":[]},{"level":2,"title":"log","slug":"log-3","link":"#log-3","children":[]},{"level":2,"title":"log","slug":"log-4","link":"#log-4","children":[]},{"level":2,"title":"log","slug":"log-5","link":"#log-5","children":[]},{"level":2,"title":"n2","slug":"n2-1","link":"#n2-1","children":[]},{"level":2,"title":"小结","slug":"小结","link":"#小结","children":[]},{"level":2,"title":"n2","slug":"n2-2","link":"#n2-2","children":[]},{"level":2,"title":"log","slug":"log-6","link":"#log-6","children":[]},{"level":2,"title":"思考题","slug":"思考题","link":"#思考题","children":[]}],"relativePath":"快速上手C++数据结构与算法/37｜简单选择排序与堆排序：多趟排序与利用有序完全二叉树进行排序.md","filePath":"快速上手C++数据结构与算法/37｜简单选择排序与堆排序：多趟排序与利用有序完全二叉树进行排序.md","lastUpdated":1795557152000}'),i={name:"快速上手C++数据结构与算法/37｜简单选择排序与堆排序：多趟排序与利用有序完全二叉树进行排序.md"};function p(t,n,r,o,E,h){return s(),l("div",null,[...n[0]||(n[0]=[e(`<h1 id="_37-简单选择排序与堆排序-多趟排序与利用有序完全二叉树进行排序" tabindex="-1">37 | 简单选择排序与堆排序：多趟排序与利用有序完全二叉树进行排序 <a class="header-anchor" href="#_37-简单选择排序与堆排序-多趟排序与利用有序完全二叉树进行排序" aria-label="Permalink to &quot;37 | 简单选择排序与堆排序：多趟排序与利用有序完全二叉树进行排序&quot;">​</a></h1><p>你好，我是王健伟。</p><p>前面我们一起学习了交换类排序，也就是在排序过程中对元素进行两两比较并交换位置。其中，最知名的交换类排序算法——冒泡排序、快速排序我们都已经讲过了。这次，我们学习一个新的排序种类——选择类排序。</p><p>选择类排序是一种基于比较的排序算法，他的基本思想就是每一趟在待排序的元素中选取关键字最小（或最大）的元素加入到有序子序列中。而简单选择排序则是选择类排序中的一种。</p><h2 id="什么是简单选择排序" tabindex="-1">什么是简单选择排序？ <a class="header-anchor" href="#什么是简单选择排序" aria-label="Permalink to &quot;什么是简单选择排序？&quot;">​</a></h2><p>简单选择排序英文名称是 Simple Selection Sort。简单选择排序需要进行多趟排序才能得到最终结果。它的基本思想是每趟从待排序的元素中找出值最小的元素放到已排序序列的末尾，然后再从未排序的元素中选择最小的元素，继续放到已排序的序列的末尾，直到所有元素都被排序完毕。</p><h3 id="简单选择排序过程演示" tabindex="-1">简单选择排序过程演示 <a class="header-anchor" href="#简单选择排序过程演示" aria-label="Permalink to &quot;简单选择排序过程演示&quot;">​</a></h3><p>以图形来说明会比较直观，如图 1 所示：</p><p><a class="image-link" href="https://raw.githubusercontent.com/qiangshuifish/note-website/note-website/%E5%BF%AB%E9%80%9F%E4%B8%8A%E6%89%8BC%2B%2B%E6%95%B0%E6%8D%AE%E7%BB%93%E6%9E%84%E4%B8%8E%E7%AE%97%E6%B3%95/images/37/1.png" target="_blank" rel="noopener" title="点击查看原图"><img src="https://raw.githubusercontent.com/qiangshuifish/note-website/note-website/%E5%BF%AB%E9%80%9F%E4%B8%8A%E6%89%8BC%2B%2B%E6%95%B0%E6%8D%AE%E7%BB%93%E6%9E%84%E4%B8%8E%E7%AE%97%E6%B3%95/images/37/1.png" alt=""></a></p><ul><li>图1 简单选择排序示意图</li></ul><p>图 1 左上侧是待排序的 10 个元素，我们以从小到大排序来说明。</p><ul><li><p>第一趟排序：从待排序的元素中找出值最小的元素和下标为 0 的元素做交换，这样下标为 0的位置所保存的就是最小值的元素，此时无需再理会下标为 0 的位置。</p></li><li><p>第二趟排序：抛开下标为 0 位置的元素，从其余元素中找出值最小的元素和下标为 1 的元素做交换，这样下标为 1 位置所保存的就是剩余待排序元素中最小值的元素，此时无需再理会下标为 1 的位置。</p></li><li><p>第三趟排序：抛开下标为 0、1 位置的元素，从其余元素中找出值最小的元素和下标为 2 的元素做交换，这样下标为 2 位置所保存的就是剩余待排序元素中最小值的元素，此时无需再理会下标为 2 的位置。</p></li><li><p>如此重复，第九趟排序：抛开下标为 0、1、2、3、4、5、6、7 位置的元素，从其余元素中找出值最小的元素和下标为 8 的元素做交换，这样下标为 8 位置所保存的就是剩余待排序元素中最小值的元素。此时，下标为 9 的元素自然就是值最大的元素。</p></li></ul><p>到这里，整个简单选择排序算法就完成了。</p><h3 id="简单选择排序实现代码" tabindex="-1">简单选择排序实现代码 <a class="header-anchor" href="#简单选择排序实现代码" aria-label="Permalink to &quot;简单选择排序实现代码&quot;">​</a></h3><p>从图 1 中可以看到，对于具有 10 个元素的数组，只需要进行 9 趟处理即可完成整个简单选择排序，具体的实现代码如下：</p><div class="language- vp-adaptive-theme"><button title="Copy Code" class="copy"></button><span class="lang"></span><pre class="shiki shiki-themes github-light github-dark vp-code" tabindex="0"><code><span class="line"><span>//简单选择排序（从小到大）</span></span>
<span class="line"><span>template&lt;​typename T&gt;</span></span>
<span class="line"><span>void SmpSelSort(T myarray[], int length)</span></span>
<span class="line"><span>{</span></span>
<span class="line"><span> for (int i = 0; i &lt; length - 1; ++i) //一共要进行length-1趟</span></span>
<span class="line"><span> {</span></span>
<span class="line"><span>   int minidx = i;  //保存最小元素位置</span></span>
<span class="line"><span>   //在myarray[i]到myarray[length-1]中选择最小值</span></span>
<span class="line"><span>   for (int j = i + 1; j &lt; length; ++j)</span></span>
<span class="line"><span>   {</span></span>
<span class="line"><span>     if (myarray[j] &lt; myarray[minidx])</span></span>
<span class="line"><span>       minidx = j; //保存最小元素值位置</span></span>
<span class="line"><span>   } //end for j</span></span>
<span class="line"><span>   if (minidx != i)</span></span>
<span class="line"><span>   {</span></span>
<span class="line"><span>     T temp = myarray[i];</span></span>
<span class="line"><span>     myarray[i] = myarray[minidx];</span></span>
<span class="line"><span>     myarray[minidx] = temp;</span></span>
<span class="line"><span>   }</span></span>
<span class="line"><span> } //end for i</span></span>
<span class="line"><span> return;</span></span>
<span class="line"><span>}</span></span></code></pre></div><p>在 main 主函数中，加入测试代码。</p><div class="language- vp-adaptive-theme"><button title="Copy Code" class="copy"></button><span class="lang"></span><pre class="shiki shiki-themes github-light github-dark vp-code" tabindex="0"><code><span class="line"><span>int arr[] = { 16,1,45,23,99,2,18,67,42,10 };</span></span>
<span class="line"><span>int length = sizeof(arr) / sizeof(arr[0]);   //数组中元素个数</span></span>
<span class="line"><span>SmpSelSort(arr, length);//对数组元素进行简单选择排序</span></span>
<span class="line"><span>cout &lt;&lt;&quot;简单选择排序结果为：&quot;;</span></span>
<span class="line"><span>for (int i = 0; i &lt; length; ++i)</span></span>
<span class="line"><span>{</span></span>
<span class="line"><span> cout &lt;&lt; arr[i] &lt;&lt;&quot; &quot;;</span></span>
<span class="line"><span>}</span></span>
<span class="line"><span>cout &lt;&lt; endl; //换行</span></span></code></pre></div><p>代码的执行结果如下：</p><p><a class="image-link" href="https://raw.githubusercontent.com/qiangshuifish/note-website/note-website/%E5%BF%AB%E9%80%9F%E4%B8%8A%E6%89%8BC%2B%2B%E6%95%B0%E6%8D%AE%E7%BB%93%E6%9E%84%E4%B8%8E%E7%AE%97%E6%B3%95/images/37/2.png" target="_blank" rel="noopener" title="点击查看原图"><img src="https://raw.githubusercontent.com/qiangshuifish/note-website/note-website/%E5%BF%AB%E9%80%9F%E4%B8%8A%E6%89%8BC%2B%2B%E6%95%B0%E6%8D%AE%E7%BB%93%E6%9E%84%E4%B8%8E%E7%AE%97%E6%B3%95/images/37/2.png" alt=""></a></p><p>该算法的时间复杂度如何呢？我们用 n 代表元素数量，无论原有数据是否有序，都需要进行</p><ul><li>n(n−1)</li></ul><p>n-1 趟处理，总共需要对比的关键字次数是 (n-1)+(n-2)+…+1=</p><ul><li>次（等差数列求和公2​</li></ul><p>式）。而需要元素交换的次数最少为 0 次，最多也不会超过 3(n-1) 次。所以，简单选择排序算</p><h2 id="n2" tabindex="-1">n2 <a class="header-anchor" href="#n2" aria-label="Permalink to &quot;n2&quot;">​</a></h2><p>法的时间复杂度为 O(</p><ul><li>)。空间复杂度为 O(1)。</li></ul><p>此外，该算法是不稳定的，只需要用一组数据 2、2、1 测试一下即可知道。如图 2 所示，前两个元素在排好序之后位置已经调换了。</p><p><a class="image-link" href="https://raw.githubusercontent.com/qiangshuifish/note-website/note-website/%E5%BF%AB%E9%80%9F%E4%B8%8A%E6%89%8BC%2B%2B%E6%95%B0%E6%8D%AE%E7%BB%93%E6%9E%84%E4%B8%8E%E7%AE%97%E6%B3%95/images/37/3.png" target="_blank" rel="noopener" title="点击查看原图"><img src="https://raw.githubusercontent.com/qiangshuifish/note-website/note-website/%E5%BF%AB%E9%80%9F%E4%B8%8A%E6%89%8BC%2B%2B%E6%95%B0%E6%8D%AE%E7%BB%93%E6%9E%84%E4%B8%8E%E7%AE%97%E6%B3%95/images/37/3.png" alt=""></a></p><ul><li>图2 简单选择排序算法不稳定性证明</li></ul><h2 id="堆排序" tabindex="-1">堆排序 <a class="header-anchor" href="#堆排序" aria-label="Permalink to &quot;堆排序&quot;">​</a></h2><p>简单选择排序说完之后，我们来说一下堆排序。这两类排序都属于选择类排序，不过两者的实现方式不同。简单选择排序是每趟从待排序的元素中找出值最小的元素放到已排序序列的末尾，直到所有元素排序完成。而堆排序是通过将待排序元素构成一个堆的方式来实现元素的排序，可以说，堆排序的效率往往更高。</p><p>那么，到底什么是“堆”呢？</p><h3 id="堆的基本概念" tabindex="-1">堆的基本概念 <a class="header-anchor" href="#堆的基本概念" aria-label="Permalink to &quot;堆的基本概念&quot;">​</a></h3><p>堆是有序的完全二叉树，这里所说的有序指的是父节点一定大于等于子节点值或者父节点一定小于等于子节点值。</p><ul><li><p>大顶堆（大根堆 / 最大堆）：父节点大于等于子节点值。</p></li><li><p>小顶堆（小根堆 / 最小堆）：父节点小于等于子节点值。</p></li></ul><p>图 3 所示为一个小顶堆和一个大顶堆：</p><p><a class="image-link" href="https://raw.githubusercontent.com/qiangshuifish/note-website/note-website/%E5%BF%AB%E9%80%9F%E4%B8%8A%E6%89%8BC%2B%2B%E6%95%B0%E6%8D%AE%E7%BB%93%E6%9E%84%E4%B8%8E%E7%AE%97%E6%B3%95/images/37/4.png" target="_blank" rel="noopener" title="点击查看原图"><img src="https://raw.githubusercontent.com/qiangshuifish/note-website/note-website/%E5%BF%AB%E9%80%9F%E4%B8%8A%E6%89%8BC%2B%2B%E6%95%B0%E6%8D%AE%E7%BB%93%E6%9E%84%E4%B8%8E%E7%AE%97%E6%B3%95/images/37/4.png" alt=""></a></p><ul><li>图3 一个小顶堆和一个大顶堆</li></ul><p>前面曾经讲解过用顺序存储方式（数组）来存储完全二叉树。此时父节点在数组中的编号（编号代表的就是位置）和子节点在数组中的编号是有对应关系的。回顾一下二叉树的性质六：如果对一棵有 n 个节点的完全二叉树的节点按层从 1 开始编号，对任意节点 i（1≤i≤n），有下面三种情况。</p><ul><li><p>如果 i=1，则节点 i 是二叉树的根，无父节点，如果 i&gt;1，则其父节点编号是⌊i/2⌋。</p></li><li><p>如果 2i&gt;n，则节点 i 为叶子节点（无孩子节点），否则，其左孩子是节点 2i。</p></li><li><p>如果 2i+1&gt;n，则节点 i 无右孩子（但可能有左孩子），否则其右孩子是节点 2i+1。</p></li></ul><p>图 3 所示的小顶堆和大顶堆所对应的存储数组就应该如图 4 所示：</p><p><a class="image-link" href="https://raw.githubusercontent.com/qiangshuifish/note-website/note-website/%E5%BF%AB%E9%80%9F%E4%B8%8A%E6%89%8BC%2B%2B%E6%95%B0%E6%8D%AE%E7%BB%93%E6%9E%84%E4%B8%8E%E7%AE%97%E6%B3%95/images/37/5.png" target="_blank" rel="noopener" title="点击查看原图"><img src="https://raw.githubusercontent.com/qiangshuifish/note-website/note-website/%E5%BF%AB%E9%80%9F%E4%B8%8A%E6%89%8BC%2B%2B%E6%95%B0%E6%8D%AE%E7%BB%93%E6%9E%84%E4%B8%8E%E7%AE%97%E6%B3%95/images/37/5.png" alt=""></a></p><ul><li>图4 图3所示小顶堆和大顶堆对应的存储数组</li></ul><p>上述做法一个不太好的地方是为写程序方便浪费了数组下标为[0]的空间。其实，把这个空间利用起来也是完全可以的。下面的堆排序实现中，即是将数组下标为[0]的空间也使用了。</p><h3 id="堆排序算法" tabindex="-1">堆排序算法 <a class="header-anchor" href="#堆排序算法" aria-label="Permalink to &quot;堆排序算法&quot;">​</a></h3><p>如果实现从小到大的排序算法，则使用大顶堆比较方便，实现出的算法占用的辅助空间更少。如果实现从大到小排序，则使用小顶堆比较方便，你可以通过阅读后面的内容慢慢体会。不过，如果使用小顶堆，可能算法需要更多的辅助空间。</p><p>堆排序就是利用堆（大顶堆或者小顶堆）进行排序的方法。这里我将采用大顶堆来实现。基本思想就是把待排序的 n 个元素的序列构造成一个大顶堆。此时，整个序列的最大值就是堆顶的根节点。将该节点数据删除，实际是将该节点数据与堆待排序序列末尾元素交换位置，然后将剩余 n-1 个元素的序列重新构造成一个大顶堆，这样根节点就是 n 个元素中的次大值……如此反复，就可以得到一个排好序的序列了。</p><p>所以，堆排序需要解决两个主要问题。</p><ol><li><p>由一个无序序列建成一个堆。</p></li><li><p>在输出堆顶元素（删除元素）后，对其余元素进行调整从而生成一个新堆。</p></li></ol><p>以数组{ 16,1,45,23,99,2,18,67,42,10 }为例，先来创建一棵完全二叉树，参考图 5：</p><p><a class="image-link" href="https://raw.githubusercontent.com/qiangshuifish/note-website/note-website/%E5%BF%AB%E9%80%9F%E4%B8%8A%E6%89%8BC%2B%2B%E6%95%B0%E6%8D%AE%E7%BB%93%E6%9E%84%E4%B8%8E%E7%AE%97%E6%B3%95/images/37/6.png" target="_blank" rel="noopener" title="点击查看原图"><img src="https://raw.githubusercontent.com/qiangshuifish/note-website/note-website/%E5%BF%AB%E9%80%9F%E4%B8%8A%E6%89%8BC%2B%2B%E6%95%B0%E6%8D%AE%E7%BB%93%E6%9E%84%E4%B8%8E%E7%AE%97%E6%B3%95/images/37/6.png" alt=""></a></p><ul><li>图5 用数组{ 16,1,45,23,99,2,18,67,42,10 } 创建的一棵完全二叉树并从0开始标注一下数组下标</li></ul><p>显然，图 5 并不是一个堆（不是大顶堆也不是小顶堆）。所以第一步先创建出一个堆。因为这里要进行从小到大排序，所以这里首先要创建一个大顶堆。大顶堆的特点是父节点大于等于子节点值。所以就要检查树中所有非叶子节点，看看这些非叶子节点是否满足大顶堆的要求，如果不满足要求，则调整成满足大顶堆的要求。非叶子节点很好找，在图 5 中，观察一下数组下标，可以看到，如果整个完全二叉树的节点有 n 个，则非叶子节点的编号 i 应该满足i≤⌊n/2⌋-1。</p><p>那么，如何调整成满足大顶堆要求呢？</p><ul><li><p>在图 5 中，从最后一个非叶子节点即以 99 为根的节点找起，不断向左上方寻找，这棵子树满足父节点大于等于子节点值的要求，无需调整。</p></li><li><p>以 23 为根的子树不满足大顶堆要求，因此节点 23 和节点 67 的值互换。如图 6 中子图 1。</p></li><li><p>以 45 为根的子树满足大顶堆要求。</p></li><li><p>以 1 为根的子树不满足大顶堆要求，因此节点 1 和节点 99 的值互换。这一互换再次导致以1 为根的子树不满足大顶堆要求，因此节点 1 又和节点 10 互换。如图 6 中子图 2。</p></li><li><p>以 16 为根的子树不满足大顶堆要求，因此节点 16 和节点 99 的值互换，如图 6 中的子图3。</p></li><li><p>此时出现了新问题，那就是此时以 16 为根的子树又不满足大顶堆要求，因此节点 16 又要和其左孩子节点 67 的值互换，如图 6 中子图 4。接着，以节点 16 为根的子树又不满足大</p></li><li><p>顶堆要求，因此节点 16 又要和其右孩子节点 42 的值互换，如图 6 中子图 5。所以这里可以看到，因为上一级元素的互换导致破坏了下一级的堆，因此要采用相同的调整方法不断向下调整。</p></li></ul><p><a class="image-link" href="https://raw.githubusercontent.com/qiangshuifish/note-website/note-website/%E5%BF%AB%E9%80%9F%E4%B8%8A%E6%89%8BC%2B%2B%E6%95%B0%E6%8D%AE%E7%BB%93%E6%9E%84%E4%B8%8E%E7%AE%97%E6%B3%95/images/37/7.png" target="_blank" rel="noopener" title="点击查看原图"><img src="https://raw.githubusercontent.com/qiangshuifish/note-website/note-website/%E5%BF%AB%E9%80%9F%E4%B8%8A%E6%89%8BC%2B%2B%E6%95%B0%E6%8D%AE%E7%BB%93%E6%9E%84%E4%B8%8E%E7%AE%97%E6%B3%95/images/37/7.png" alt=""></a></p><ul><li>图6 将一棵完全二叉树调整为大顶堆</li></ul><p>如图 6，将一棵完全二叉树调整为大顶堆后，最大值也就得到了，正是根元素。把该值找一个适当的位置保存，然后将完全二叉树中剩余的节点中的最后一个节点放到根节点的位置，再把这个换了根的完全二叉树重复上面的步骤调整为大顶堆，这样就可以找到次大值了。如图 7 所示：</p><p><a class="image-link" href="https://raw.githubusercontent.com/qiangshuifish/note-website/note-website/%E5%BF%AB%E9%80%9F%E4%B8%8A%E6%89%8BC%2B%2B%E6%95%B0%E6%8D%AE%E7%BB%93%E6%9E%84%E4%B8%8E%E7%AE%97%E6%B3%95/images/37/8.png" target="_blank" rel="noopener" title="点击查看原图"><img src="https://raw.githubusercontent.com/qiangshuifish/note-website/note-website/%E5%BF%AB%E9%80%9F%E4%B8%8A%E6%89%8BC%2B%2B%E6%95%B0%E6%8D%AE%E7%BB%93%E6%9E%84%E4%B8%8E%E7%AE%97%E6%B3%95/images/37/8.png" alt=""></a></p><ul><li>图7 继续将一棵完全二叉树调整为大顶堆</li></ul><p>如此反复，最终就可以得到从小到大的排好序的序列了。</p><h3 id="堆排序实现代码" tabindex="-1">堆排序实现代码 <a class="header-anchor" href="#堆排序实现代码" aria-label="Permalink to &quot;堆排序实现代码&quot;">​</a></h3><p>堆排序算法的实现代码如下：</p><div class="language- vp-adaptive-theme"><button title="Copy Code" class="copy"></button><span class="lang"></span><pre class="shiki shiki-themes github-light github-dark vp-code" tabindex="0"><code><span class="line"><span>//调整以curpos为根的子树为大顶堆（这里要一直向下调整到尾部叶子才能结束）</span></span>
<span class="line"><span>template&lt;​typename T&gt;</span></span>
<span class="line"><span>void AdjustDown(T myarray[], int length, int curpos) //length：堆中元素个数，curpos</span></span>
<span class="line"><span>{</span></span>
<span class="line"><span> int i = curpos;  //4，当前节点下标</span></span>
<span class="line"><span> int j = 2 * i + 1; //9，左子节点下标</span></span>
<span class="line"><span> while (j &lt; length)//i有左子节点</span></span>
<span class="line"><span> {</span></span>
<span class="line"><span>   //找左右子节点中值比较大的节点，让j指向该节点</span></span>
<span class="line"><span>   if (j &lt; length - 1) //i也有右子树</span></span>
<span class="line"><span>   {</span></span>
<span class="line"><span>     if (myarray[j] &lt; myarray[j + 1]) //如果左子节点值&lt;右子节点值</span></span>
<span class="line"><span>       j = (j + 1); //让j始终指向值最大的子节点。</span></span>
<span class="line"><span>   }</span></span>
<span class="line"><span>   if (myarray[i] &gt;= myarray[j]) //父节点保持值最大</span></span>
<span class="line"><span>     break; //不需要调整直接break;</span></span>
<span class="line"><span>   //走到这里表示孩子节点比父亲节点大，那么就要进行父子位置交换了</span></span>
<span class="line"><span>   T temp = myarray[i];</span></span>
<span class="line"><span>   myarray[i] = myarray[j];</span></span>
<span class="line"><span>   myarray[j] = temp;</span></span>
<span class="line"><span>   //交换数据之后，可能就会影响到下一层了。所以还要继续向下调整</span></span>
<span class="line"><span>   i = j;</span></span>
<span class="line"><span>   j = 2 * i + 1;</span></span>
<span class="line"><span> }//end while</span></span>
<span class="line"><span> return;</span></span>
<span class="line"><span>}</span></span>
<span class="line"><span>//把最大值从大顶堆中删除掉，把尾元素移动到首部并且继续调整为大顶堆</span></span>
<span class="line"><span>template&lt;​typename T&gt;</span></span>
<span class="line"><span>void RemoveMaxValue(T myarray[], int length) //length:堆中元素个数</span></span>
<span class="line"><span>{</span></span>
<span class="line"><span> if (length == 0) //就一个元素了，就不需要调整了本身就认为是堆了</span></span>
<span class="line"><span>   return;</span></span>
<span class="line"><span> T temp = myarray[0]; //该位置元素值最大</span></span>
<span class="line"><span> myarray[0] = myarray[length]; //将最后一个元素放到最上面位置，等价于最上面位置元素被删除</span></span>
<span class="line"><span> myarray[length] = temp;</span></span>
<span class="line"><span> AdjustDown(myarray, length, 0);</span></span>
<span class="line"><span> return;</span></span>
<span class="line"><span>}</span></span>
<span class="line"><span>//堆排序（从小到大）</span></span>
<span class="line"><span>template&lt;​typename T&gt;</span></span>
<span class="line"><span>void HeapSelSort(T myarray[], int length)</span></span>
<span class="line"><span>{</span></span>
<span class="line"><span> //(1)由一个无序序列建成一个大顶堆</span></span>
<span class="line"><span> //现在要把myarray数组调整为大顶堆（检查树中所有非叶子节点，看看这些非叶子节点是否满足大顶堆的</span></span>
<span class="line"><span> int curpos = length / 2 - 1;//非叶子节点的位置</span></span>
<span class="line"><span> while (curpos &gt;= 0) //逐渐向树的根部调整</span></span>
<span class="line"><span> {</span></span>
<span class="line"><span>   //要从当前节点向下调整的</span></span>
<span class="line"><span>   AdjustDown(myarray, length, curpos);</span></span>
<span class="line"><span>   curpos--;</span></span>
<span class="line"><span> } //end while</span></span>
<span class="line"><span> //(2)通过大顶堆来进行排序</span></span>
<span class="line"><span> for (int i = 0; i &lt; length; ++i)</span></span>
<span class="line"><span> {</span></span>
<span class="line"><span>   RemoveMaxValue(myarray, length - i - 1); //把最大值从大顶堆中删除掉，并重新整理使之再</span></span>
<span class="line"><span> } //end for i</span></span>
<span class="line"><span> return;</span></span>
<span class="line"><span>}</span></span></code></pre></div><p>在 main 主函数中的代码如下：</p><div class="language- vp-adaptive-theme"><button title="Copy Code" class="copy"></button><span class="lang"></span><pre class="shiki shiki-themes github-light github-dark vp-code" tabindex="0"><code><span class="line"><span>int arr[] = { 16,1,45,23,99,2,18,67,42,10 };</span></span>
<span class="line"><span>int length = sizeof(arr) / sizeof(arr[0]);   //数组中元素个数</span></span>
<span class="line"><span>HeapSelSort(arr, length);</span></span>
<span class="line"><span>cout &lt;&lt;&quot;堆排序结果为：&quot;;</span></span>
<span class="line"><span>for (int i = 0; i &lt; length; ++i)</span></span>
<span class="line"><span>{</span></span>
<span class="line"><span> cout &lt;&lt; arr[i] &lt;&lt;&quot; &quot;;</span></span>
<span class="line"><span>}</span></span>
<span class="line"><span>cout &lt;&lt; endl; //换行</span></span></code></pre></div><p>代码的执行结果如下：</p><p><a class="image-link" href="https://raw.githubusercontent.com/qiangshuifish/note-website/note-website/%E5%BF%AB%E9%80%9F%E4%B8%8A%E6%89%8BC%2B%2B%E6%95%B0%E6%8D%AE%E7%BB%93%E6%9E%84%E4%B8%8E%E7%AE%97%E6%B3%95/images/37/9.png" target="_blank" rel="noopener" title="点击查看原图"><img src="https://raw.githubusercontent.com/qiangshuifish/note-website/note-website/%E5%BF%AB%E9%80%9F%E4%B8%8A%E6%89%8BC%2B%2B%E6%95%B0%E6%8D%AE%E7%BB%93%E6%9E%84%E4%B8%8E%E7%AE%97%E6%B3%95/images/37/9.png" alt=""></a></p><p>当然，通过对上述代码的改造，实现小顶堆也不困难。</p><h3 id="堆中元素的插入和删除" tabindex="-1">堆中元素的插入和删除 <a class="header-anchor" href="#堆中元素的插入和删除" aria-label="Permalink to &quot;堆中元素的插入和删除&quot;">​</a></h3><p>实际上，通过对上述代码的学习。向堆中插入元素和从堆中删除元素的代码也是很容易书写的，当然要注意堆中有足够的空间以容纳新插入的元素。</p><p>这里我给出实现思路，具体的实现代码你可以尝试自己完成。</p><ol><li>向大顶堆中插入新元素。</li></ol><ul><li><p>将新元素放到堆的最后位置。</p></li><li><p>将新元素与其父节点元素做对比，若新元素值比其父节点元素值大，则将两者互换。</p></li><li><p>就这样不断将新元素向树根方向（向上）调整，一直到新元素无法向上调整为止。因为这意味着新元素值小于等于其父节点元素值了。</p></li><li><p>每次向上调整需要对比关键字一次。</p></li></ul><ol start="2"><li>从大顶堆中删除一个元素。</li></ol><ul><li><p>因为删除元素后，原来该元素的位置会被空出来，所以用堆中最后位置的元素填补空出的这个位置。</p></li><li><p>让该元素和其子节点对比，若该元素比其子节点元素值小，则两者互换。若该元素有两个孩子，则和值大的孩子互换。</p></li><li><p>这样不断将新元素向下调整，一直到该元素无法向下调整为止（即没有子节点或者子节点比该元素值小）。</p></li><li><p>每次向下调整需要对比关键字一次（只有一个子节点）或者两次（有两个子节点）。</p></li></ul><p>总结下来你会发现，不管大顶堆还是小顶堆插入新元素都是不断向上调整该元素。删除老元素都是不断向下调整被填补的元素。</p><h3 id="堆排序算法效率分析" tabindex="-1">堆排序算法效率分析 <a class="header-anchor" href="#堆排序算法效率分析" aria-label="Permalink to &quot;堆排序算法效率分析&quot;">​</a></h3><p>考虑到堆排序会花费时间来构建初始堆以及不断调整新堆以排序，所以我们一般在排序的数据记录比较多的时候采用这类方式。下面我们来分析一下这个算法的复杂度。</p><ol><li>对于有 n 条记录的序列，构建初始堆，因为对于该完全二叉树是从最下层最右侧的非叶子节点开始构建——该节点与孩子节点比较，若有必要则进行数据交换，所以对于每个非叶子节点一般会进行两次比较，也就是既和左孩子节点比较也和右孩子节点比较，当然，还有一次数据交换操作。不过，数据交换可能导致破坏下一级，所以还要对下一级继续做调整。</li></ol><p>下面的一些信息可以辅助分析堆排序的算法效率问题：</p><ul><li>如果树的高度为 h，某个节点位于第 i 层，则对该节点逐渐做向下一级的调整，该节点可能会下落 h-i 层，关键字的对比次数不超过 2(h-i)。</li></ul><h2 id="_2i−1" tabindex="-1">2i−1 <a class="header-anchor" href="#_2i−1" aria-label="Permalink to &quot;2i−1&quot;">​</a></h2><ul><li>第 i 层最多有个节点，而其中的第 1 到 h-1 层的节点才可能需要下落。n根据二叉树的性质五——对于一个有 n 个节点的完全二叉树高度为⌊⌋ +1。</li></ul><h2 id="log" tabindex="-1">log <a class="header-anchor" href="#log" aria-label="Permalink to &quot;log&quot;">​</a></h2><ul><li>​2</li></ul><p>针对上述信息，有一个复杂的公式推导，最后推导出一个结论：将整棵树调整为大顶堆，关键字对比次数不超过 4n。这里你只需要简单知道一下就可以，如果有兴趣深究可以通过搜索引擎了解。所以构建初始堆的时间复杂度为 O(n)。</p><ol start="2"><li>正式排序的时候，每次都将最后一条记录放入到最前面并重新构建堆，这样的动作重复了n-1 次。</li></ol><ul><li>n</li></ul><p>对于一个有 n 个节点的完全二叉树高度为⌊</p><ul><li>⌋ +1 意味着每次重新构建堆的时间复杂度是 O(</li></ul><h2 id="log-1" tabindex="-1">log <a class="header-anchor" href="#log-1" aria-label="Permalink to &quot;log&quot;">​</a></h2><ul><li>​2nn</li></ul><h2 id="log-2" tabindex="-1">log <a class="header-anchor" href="#log-2" aria-label="Permalink to &quot;log&quot;">​</a></h2><h2 id="log-3" tabindex="-1">log <a class="header-anchor" href="#log-3" aria-label="Permalink to &quot;log&quot;">​</a></h2><ul><li>)，那么整个算法重新构建堆的时间复杂度就应该是 O(n)。​2​2</li></ul><ol start="3"><li>nn</li></ol><h2 id="log-4" tabindex="-1">log <a class="header-anchor" href="#log-4" aria-label="Permalink to &quot;log&quot;">​</a></h2><h2 id="log-5" tabindex="-1">log <a class="header-anchor" href="#log-5" aria-label="Permalink to &quot;log&quot;">​</a></h2><ul><li>对于 O(n)+O(n) 会保留大值的原则，所以总体来说，堆排序的时间复杂度是 O(n​2​2</li></ul><h2 id="n2-1" tabindex="-1">n2 <a class="header-anchor" href="#n2-1" aria-label="Permalink to &quot;n2&quot;">​</a></h2><ul><li>)，从性能上比很多时间复杂度为 O() 的排序算法要好很多。</li></ul><p>另外，堆排序的空间复杂度为 O(1)。</p><p>最后，你可以想一想，堆排序算法的稳定性如何呢？该算法是不稳定的，如图 8 所示：</p><p><a class="image-link" href="https://raw.githubusercontent.com/qiangshuifish/note-website/note-website/%E5%BF%AB%E9%80%9F%E4%B8%8A%E6%89%8BC%2B%2B%E6%95%B0%E6%8D%AE%E7%BB%93%E6%9E%84%E4%B8%8E%E7%AE%97%E6%B3%95/images/37/10.png" target="_blank" rel="noopener" title="点击查看原图"><img src="https://raw.githubusercontent.com/qiangshuifish/note-website/note-website/%E5%BF%AB%E9%80%9F%E4%B8%8A%E6%89%8BC%2B%2B%E6%95%B0%E6%8D%AE%E7%BB%93%E6%9E%84%E4%B8%8E%E7%AE%97%E6%B3%95/images/37/10.png" alt=""></a></p><ul><li>图8 堆排序算法不稳定性证明</li></ul><p>从图 8 可以看到，将排序的数字 10、1、10。从小到大排序后，得到的结果虽然是 1、10、10，但显然，后面两个 10 的相对位置已经改变了。当然，读者也可以对上述实现代码进行调整，然后换一些其他数据尝试，仍旧会得到同样的结论。</p><h2 id="小结" tabindex="-1">小结 <a class="header-anchor" href="#小结" aria-label="Permalink to &quot;小结&quot;">​</a></h2><p>本节我们首先介绍了新的排序种类——选择类排序。这类排序的基本思想就是每一趟在待排序的元素中选取关键字最小（或最大）的元素加入到有序子序列中。</p><p>简单选择排序是选择类排序中的一种。其基本思想是每趟从待排序的元素中找出值最小的元素放到已排序序列的末尾。然后再从未排序的元素中选择最小的元素，继续放到已排序的序列的末尾，重复多趟，直到所有元素都被排序完毕。</p><h2 id="n2-2" tabindex="-1">n2 <a class="header-anchor" href="#n2-2" aria-label="Permalink to &quot;n2&quot;">​</a></h2><p>我也给出了简单选择排序的实现代码。简单选择排序算法的时间复杂度为 O(</p><ul><li>)。空间复杂度</li></ul><p>为 O(1)。简单选择排序算法属于不稳定算法。</p><p>接着我向你选择类排序中的另一种——堆排序。这里需要你先理解大顶堆和小顶堆的简单概念，然后再去理解堆排序的基本思想：将待排序序列构建成一个堆，堆顶元素即为最大值或最小值，然后将堆顶元素与堆末尾元素交换，再将剩余元素重新构建成一个堆，重复此过程直至所有元素排序完成。</p><p>同样，我详细向你介绍了堆排序的过程并给出了堆排序的实现代码。堆排序的时间复杂度为</p><ul><li>n</li></ul><h2 id="log-6" tabindex="-1">log <a class="header-anchor" href="#log-6" aria-label="Permalink to &quot;log&quot;">​</a></h2><p>O(n</p><ul><li>)，空间复杂度为 O(1)。堆排序算法属于不稳定算法。​2</li></ul><p>不难看到，堆排序的时间复杂度更优秀。而且待排序元素越多，这种优秀程度体现得越明显。</p><h2 id="思考题" tabindex="-1">思考题 <a class="header-anchor" href="#思考题" aria-label="Permalink to &quot;思考题&quot;">​</a></h2><ol><li><p>对于一个长度为 n 的数组，我们不排序，而是参考简单选择排序算法的实现代码将其中奇数放到前面，偶数放到后面，并且奇数和偶数内部的相对顺序不变（原来排在前面的奇数依旧排在前面，原来排在后面的奇数依旧排在后面，偶数也一样），可以怎么做？。</p></li><li><p>在堆排序算法中，若要对一个有 10 个元素的数组进行排序，最多需要进行多少次比较和数值交换操作？</p></li></ol><p>欢迎你在留言区和我交流。如果觉得有所收获，也可以把课程分享给更多的朋友一起学习。我们下节课见！</p>`,126)])])}const g=a(i,[["render",p]]);export{u as __pageData,g as default};
